            this.style = style;
            return this;
        }

        /** Bind the checked state (two-way). */
        public Config isOn(WritableSignal<Boolean> binding) {
            this.binding = binding;
            return this;
        }

        /** Set a static label. */
        public Config label(String label) {
            this.label = Signals.constant(label);
            return this;
        }

